import pandas as pd, numpy as np, warnings
from scipy import stats
warnings.filterwarnings('ignore')
pd.set_option('display.width',220); pd.set_option('display.max_columns',60); pd.set_option('display.float_format',lambda v:f'{v:.3f}')
D=pd.read_pickle('D117.pkl'); R=D[D.adv_dec==0]   # R: gercek kararlar (ilerletilen 69 karar varsayilan 0)
def tab(d,lab):
    t=d.groupby('pos').agg(ort=('contribution','mean'),sd=('contribution','std'),medyan=('contribution','median'),sifir=('contribution',lambda x:(x==0).mean()),tam=('contribution',lambda x:(x==15).mean()),share=('share','mean'),n=('contribution','size'))
    print(f'\n== {lab}'); print(t.loc[['control','cycle','center','periphery']])
    print(f'genel ort {d.contribution.mean():.3f} (endowment payi {d.contribution.mean()/15:.3f}), sifir {(d.contribution==0).mean():.3f}, tam {(d.contribution==15).mean():.3f}, ic bolge {((d.contribution>0)&(d.contribution<15)).mean():.3f}')
tab(D,'Tum 2106 karar (117 kisi)'); tab(R,'Gercek kararlar (ilerletilen 69 karar haric)'); tab(D[D.veri_seti_3==1],'Set 3 (111 kisi) - saglamlik')
print('\n== Tur bazinda ortalama katki (gercek kararlar)')
print(R.groupby('round_number').contribution.mean().round(2).to_dict())
print('Sifir orani tur 1 -> 18:',round((R[R.round_number==1].contribution==0).mean(),3),round((R[R.round_number==18].contribution==0).mean(),3))
print('Ilk 3 tur / son 3 tur:',round(R[R.round_number<=3].contribution.mean(),2),round(R[R.round_number>=16].contribution.mean(),2))
print('Blok sirasina gore ort:',R.groupby('block_index').contribution.mean().round(2).to_dict(),'| blok ici tura gore:',R.groupby('block_round').contribution.mean().round(2).to_dict())
print('Odak noktalari (5 katlari):',round(R.contribution.isin([0,5,10,15]).mean(),3),{k:round((R.contribution==k).mean(),3) for k in [0,5,10,15]})
print('\n== Oturumlara gore (gercek kararlar)')
print(R.groupby(['session_date','session_code']).agg(N=('pid','nunique'),ort=('contribution','mean'),sifir=('contribution',lambda x:(x==0).mean())))
Gs=R.groupby(['session_code','gid']).contribution.mean().reset_index()
print('Grup ortalamalari oturumlar arasi Kruskal-Wallis p =',round(stats.kruskal(*[g.contribution for _,g in Gs.groupby('session_code')]).pvalue,3))
P=D.groupby('pid').first()
Pv=P[P.svy_invalid==0]
print('\n== Katilimci duzeyi (anketi gecerli',len(Pv),'kisi)')
print('cinsiyet:',Pv.gender.value_counts().to_dict()); print('alan:',Pv.field_of_study.value_counts().to_dict()); print('yas:',Pv.age.value_counts().to_dict())
c=Pv.charity_d1; print(f'LOSEV bagisi: ort {c.mean():.1f}, medyan {c.median():.0f}, sd {c.std():.1f}, 100 bagislayan {(c==100).mean():.3f}, 0 bagislayan {(c==0).mean():.3f}, 50 ve alti {(c<=50).mean():.3f}')
print('Bagis dagilimi:',c.value_counts().sort_index().to_dict())
print(f'Oyun kazanci TL: ort {P.game_total_tl.mean():.1f}; nihai odeme ort {P.final_total_tl.mean():.1f}')
# bagis payi vs oyundaki Control share (CD'de ikisi de B_i)
RS=R[R.pos.isin(['control','cycle'])].groupby('pid').share.mean()
x=pd.concat([RS.rename('share_reg'),Pv.charity_d1/100],axis=1).dropna()
print(f'Dictator payi (bagis/100) ort {x.charity_d1.mean():.3f} vs oyundaki giving share (Control+Cycle) ort {x.share_reg.mean():.3f}; Wilcoxon p={stats.wilcoxon(x.charity_d1,x.share_reg).pvalue:.2e}; Spearman rho={stats.spearmanr(x.charity_d1,x.share_reg)[0]:.3f} (p={stats.spearmanr(x.charity_d1,x.share_reg)[1]:.3f})')
